from collections import defaultdict
from typing import List

def reachableNodes(n: int, edges: List[List[int]], restricted: List[int]) -> int:
    # Build adjacency list for the tree
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Use a set for O(1) restricted node checks
    restricted_set = set(restricted)
    visited = {0}

    # Iterative DFS (a recursive one could exceed Python's recursion limit for n up to 10^5)
    stack = [0]
    while stack:
        node = stack.pop()
        for neighbor in graph[node]:
            if neighbor not in visited and neighbor not in restricted_set:
                visited.add(neighbor)
                stack.append(neighbor)

    return len(visited)
